local KitchenScaleMaker = {}
local PRODUCTS = {
    simple_iron_kitchen_scale = { name = "Preproste železne kuhinjske tehtnice", ironCost = 2, brassCost = 1, time = 4, cost = 100, culinary = 18, happiness = 1, description = "Preproste železne kuhinjske tehtnice za merjenje." }
    , brass_bearing_scale = { name = "Medeninastoležajne tehtnice", ironCost = 2, brassCost = 2, time = 6, cost = 280, culinary = 32, happiness = 1, prestige = 2, description = "Medeninastoležajne tehtnice za trgovce." },
    silver_pan_scale = { name = "Srebrnolatežne tehtnice", ironCost = 2, silverCost = 1, brassCost = 2, time = 9, cost = 680, culinary = 48, happiness = 2, prestige = 6, description = "Srebrnolatežne tehtnice za plemiče." },
    gold_trimmed_scale = { name = "Zlatookrasne tehtnice", ironCost = 2, goldCost = 1, silverCost = 1, brassCost = 2, time = 13, cost = 1600, culinary = 62, happiness = 3, prestige = 14, description = "Zlatookrasne tehtnice za visoke plemiče." },
    jewel_set_scale = { name = "Draguljasta tehtnice", ironCost = 2, goldCost = 1, silverCost = 1, brassCost = 2, jewelCost = 1, time = 17, cost = 3600, culinary = 78, happiness = 5, prestige = 27, description = "Tehtnice z draguljem za visoko plemstvo." },
    royal_grand_kitchen_scale = { name = "Kraljevski veliki kuhinjske tehtnice", ironCost = 3, goldCost = 2, silverCost = 2, brassCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 7500, culinary = 95, happiness = 12, prestige = 58, description = "Velike kraljevske kuhinjske tehtnice z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    scale_workshop = { name = "Tehtniška delavnica", cost = { gold = 280, wood = 120, stone = 120, iron = 6, brass = 6 }, upkeep = 6, qualityBonus = 5 },
    instrument_loft = { name = "Inštrumentna podstrešje", cost = { gold = 1000, wood = 240, stone = 240, silver = 6, brass = 8 }, upkeep = 23, qualityBonus = 18 },
    master_scale_atelier = { name = "Mojstrski tehtniški atelje", cost = { gold = 2700, wood = 360, stone = 480, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_instrument_palace = { name = "Kraljevska inštrumentna palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
KitchenScaleMaker.ironStock = 14; KitchenScaleMaker.brassStock = 14; KitchenScaleMaker.silverStock = 6; KitchenScaleMaker.goldStock = 6; KitchenScaleMaker.jewelStock = 4; KitchenScaleMaker.pearlStock = 4
KitchenScaleMaker.productStock = {}; KitchenScaleMaker.buildings = {}; KitchenScaleMaker.maker = nil; KitchenScaleMaker.activeMaking = {}; KitchenScaleMaker.totalProducts = 0; KitchenScaleMaker.dayTimer = 0
function KitchenScaleMaker.init() KitchenScaleMaker.ironStock=14; KitchenScaleMaker.brassStock=14; KitchenScaleMaker.silverStock=6; KitchenScaleMaker.goldStock=6; KitchenScaleMaker.jewelStock=4; KitchenScaleMaker.pearlStock=4; KitchenScaleMaker.productStock={}; KitchenScaleMaker.buildings={}; KitchenScaleMaker.maker=nil; KitchenScaleMaker.activeMaking={}; KitchenScaleMaker.totalProducts=0; KitchenScaleMaker.dayTimer=0; print("[KitchenScaleMaker] Royal Kitchen Scale Maker System initialized (6 products, 4 buildings)") end
function KitchenScaleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; KitchenScaleMaker.maker={name=n or ("Tehtničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtničar najet: %s (spretnost: %d)",KitchenScaleMaker.maker.name,s),"success") end; return true end
function KitchenScaleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function KitchenScaleMaker.build(id) local ok,e=KitchenScaleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(KitchenScaleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function KitchenScaleMaker.getQualityBonus() local b=0; for _,bd in ipairs(KitchenScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function KitchenScaleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and KitchenScaleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and KitchenScaleMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and KitchenScaleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and KitchenScaleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and KitchenScaleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and KitchenScaleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #KitchenScaleMaker.buildings==0 then return false,"Potrebna tehtniška delavnica" end; if not KitchenScaleMaker.maker then return false,"Potreben tehtničar" end; return true end
function KitchenScaleMaker.make(pt,qty) qty=qty or 1; local ok,e=KitchenScaleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then KitchenScaleMaker.ironStock=KitchenScaleMaker.ironStock-d.ironCost*qty end; if d.brassCost then KitchenScaleMaker.brassStock=KitchenScaleMaker.brassStock-d.brassCost*qty end; if d.silverCost then KitchenScaleMaker.silverStock=KitchenScaleMaker.silverStock-d.silverCost*qty end; if d.goldCost then KitchenScaleMaker.goldStock=KitchenScaleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then KitchenScaleMaker.jewelStock=KitchenScaleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then KitchenScaleMaker.pearlStock=KitchenScaleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if KitchenScaleMaker.maker then t=math.max(1,t-math.floor(KitchenScaleMaker.maker.skill/13)) end; table.insert(KitchenScaleMaker.activeMaking,{id="kitchenscale_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,culinary=d.culinary or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function KitchenScaleMaker.completeMaking(m) local q=1.0+(KitchenScaleMaker.getQualityBonus()/100); if KitchenScaleMaker.maker then q=q+(KitchenScaleMaker.maker.skill/140) end; q=math.min(2.5,q); KitchenScaleMaker.productStock[m.productType]=(KitchenScaleMaker.productStock[m.productType] or 0)+m.quantity; KitchenScaleMaker.totalProducts=KitchenScaleMaker.totalProducts+m.quantity; if m.culinary>0 and _G.state then _G.state.culinary=(_G.state.culinary or 0)+m.culinary end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if KitchenScaleMaker.maker then KitchenScaleMaker.maker.itemsMade=KitchenScaleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then KitchenScaleMaker.maker.skill=math.min(100,KitchenScaleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tehtnice izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"kitchenscale.completed",{productName=m.productName,culinary=m.culinary,prestige=m.prestige,happiness=m.happiness}) end end
function KitchenScaleMaker.update(dt) if not _G.state then return end; KitchenScaleMaker.dayTimer=KitchenScaleMaker.dayTimer+dt; if KitchenScaleMaker.dayTimer>=30 then KitchenScaleMaker.dayTimer=0; for i=#KitchenScaleMaker.activeMaking,1,-1 do local m=KitchenScaleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then KitchenScaleMaker.completeMaking(m); table.remove(KitchenScaleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(KitchenScaleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if KitchenScaleMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function KitchenScaleMaker.getStats() return {ironStock=KitchenScaleMaker.ironStock,brassStock=KitchenScaleMaker.brassStock,silverStock=KitchenScaleMaker.silverStock,goldStock=KitchenScaleMaker.goldStock,jewelStock=KitchenScaleMaker.jewelStock,pearlStock=KitchenScaleMaker.pearlStock,productStock=KitchenScaleMaker.productStock,numBuildings=#KitchenScaleMaker.buildings,hasMaker=KitchenScaleMaker.maker~=nil,makerName=KitchenScaleMaker.maker and KitchenScaleMaker.maker.name or "—",makerSkill=KitchenScaleMaker.maker and KitchenScaleMaker.maker.skill or 0,activeMaking=#KitchenScaleMaker.activeMaking,totalProducts=KitchenScaleMaker.totalProducts} end
return KitchenScaleMaker
